import java.util.*;

class Solution {
  public String rearrangeString(String s, int k) {
    if (k <= 1) return s;
    int[] count = new int[26];
    for (char c : s.toCharArray()) count[c - 'a']++;
    PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[1] != b[1] ? b[1] - a[1] : a[0] - b[0]);
    for (int c = 0; c < 26; c++) if (count[c] > 0) heap.add(new int[] {c, count[c]});
    Deque<int[]> cooling = new ArrayDeque<>(); // letters used in the last k - 1 positions
    StringBuilder sb = new StringBuilder();
    while (!heap.isEmpty()) {
      int[] top = heap.poll();
      sb.append((char) ('a' + top[0]));
      top[1]--;
      cooling.add(top);
      if (cooling.size() >= k) {
        int[] back = cooling.poll();
        if (back[1] > 0) heap.add(back);
      }
    }
    return sb.length() == s.length() ? sb.toString() : "";
  }
}
